function anioHoroscopo(fecha) {
  const y = Number(String(fecha).slice(0, 4)), m = Number(String(fecha).slice(5, 7));
  return m >= 11 ? y + 1 : y;
}
function horoscopoAnual(fecha) {
  const anio = anioHoroscopo(fecha), panel = HORO_ANUAL[anio] || "";
  let boton = false, puesto = false;
  const b = (v, es, en) => `<button type="button" class="moneda horo-btn" data-v="${v}" aria-pressed="false" aria-controls="horoAnual" data-no-tr><span class="mn">`
    + `<span class="ha-l-es">${es}</span><span class="ha-l-en" lang="en">${en}</span></span></button>`;
  return {
    cabeza: { element(e) { e.append(HORO_ANUAL_CSS, { html: true }); } },
    vista: { element(e) {
      if (!panel || boton) return;
      boton = true;
      e.setAttribute("class", `${e.getAttribute("class") || ""} cn-cuatro`.trim());
      e.append(b("anio", `Horóscopo año ${anio}`, `${anio} Horoscope`) + b("chino", `Horóscopo chino ${anio}`, `${anio} Chinese Horoscope`), { html: true });
    } },
    signos: { element(e) { if (!panel || !boton || puesto) return; puesto = true; e.after(panel, { html: true }); } },
    cuerpo: { element(e) { e.onEndTag((t) => { if (puesto) t.before(HORO_ANUAL_JS, { html: true }); }); } },
  };
}
